using System.Text.Json.Nodes;
namespace Tests;
public class AdminFeedbackTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Admin_feedback_settings_lists_and_atomic_listing_takedown()
    {
        var admin=await Admin();var seller=await LoginPhone("9877000001","Synthetic Feedback Owner");var sid=(await seller.Post("/api/seller/register",new{display_name="Synthetic Moderation Store"})).Json["id"]!.GetValue<string>();var customer=await LoginPhone("9877000002","Synthetic Reporter");var cat=Guid.NewGuid();await ApiFactory.DbExecAsync("INSERT INTO categories(id,name,slug,image_url,commission_bps,default_gst_bps,position,is_active,required_details)VALUES(@cat,'Synthetic Admin Feedback','synthetic-admin-feedback','',1000,500,0,1,'[]')",new{cat});var p=(await seller.Post("/api/seller/products",new{category_id=cat,title="Synthetic Moderation Cotton Shirt",hsn_code="6205",gst_bps=500,variants=new[]{new{sku="ADMIN-FEEDBACK-SKU",mrp_paise=20000,price_paise=10000,stock=10}}})).Json;var pid=p["id"]!.GetValue<string>();await ApiFactory.DbExecAsync("UPDATE products SET status='approved' WHERE id=@pid",new{pid});
        var support=await Staff(admin,"feedbacksupport@example.test","support");Assert.Equal(403,(await support.Get("/api/admin/reviews")).Status);Assert.Equal(403,(await customer.Get("/api/admin/product-reports")).Status);
        var r=await admin.Get("/api/admin/review-settings");Assert.True(r.Status==200,r.ToString());Assert.NotEmpty(r.Json["default_topics"]!.AsArray());
        r=await admin.Put("/api/admin/review-settings",new{feature_reviews=false,photos=false,max_photos=3});Assert.True(r.Status==200,r.ToString());Assert.False(r.Json["feature_reviews"]!.GetValue<bool>());Assert.False(r.Json["photos"]!.GetValue<bool>());
        Assert.Equal("invalid_setting",(await admin.Put("/api/admin/review-settings",new{feature_reviews=true,max_photos=99})).ErrorCode);Assert.False((await admin.Get("/api/admin/review-settings")).Json["feature_reviews"]!.GetValue<bool>());
        await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_review_settings_fail BEFORE UPDATE ON platform_settings FOR EACH ROW BEGIN IF NEW.`key`='reviews' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic review settings rollback'; END IF; END");try{Assert.Equal(500,(await admin.Put("/api/admin/review-settings",new{feature_reviews=true,max_photos=4})).Status);Assert.False((await admin.Get("/api/admin/review-settings")).Json["feature_reviews"]!.GetValue<bool>());}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_review_settings_fail");}
        var review=Guid.NewGuid();await ApiFactory.DbExecAsync("INSERT INTO reviews(id,product_id,user_id,verified,rating,title,body,status,media,media_status,seller_reply,helpful_count,report_count)VALUES(@review,@pid,@uid,1,4,'Synthetic review','Synthetic review body','pending','[{\"url\":\"/media/synthetic.webp\"}]','pending','',2,1)",new{review,pid,uid=customer.Id});await ApiFactory.DbExecAsync("INSERT INTO review_reports(id,review_id,user_id,reason,note,status,created_at)VALUES(@id,@review,@uid,'spam','Synthetic concern','open',UTC_TIMESTAMP(6))",new{id=Guid.NewGuid(),review,uid=seller.Id});
        r=await admin.Get($"/api/admin/reviews?status=pending&rating=4&reported=true&media=true&media_pending=true&seller_id={sid}&q=Synthetic");Assert.True(r.Status==200,r.ToString());Assert.Equal(1,r.Json["total"]!.GetValue<long>());Assert.Equal(1,r.Json["counts"]!["media_pending"]!.GetValue<long>());Assert.Equal("Synthetic Reporter",r.Json["items"]![0]!["author"]!.GetValue<string>());Assert.Equal("Spam or advertising",r.Json["items"]![0]!["reports"]![0]!["reason"]!.GetValue<string>());Assert.Equal(0,(await admin.Get("/api/admin/reviews?rating=2")).Json["total"]!.GetValue<long>());
        var report=Guid.NewGuid();var other=Guid.NewGuid();foreach(var id in new[]{report,other})await ApiFactory.DbExecAsync("INSERT INTO product_reports(id,product_id,seller_id,user_id,reason,note,url,status,admin_note,seller_note)VALUES(@id,@pid,@sid,@uid,'wrong_price','Synthetic listing concern','','open','','')",new{id,pid,sid,uid=customer.Id});
        r=await admin.Get("/api/admin/product-reports?q=Moderation&reason=wrong_price");Assert.Equal(2,r.Json["total"]!.GetValue<long>());Assert.Equal(2,r.Json["items"]![0]!["open_for_product"]!.GetValue<long>());Assert.Equal("Synthetic Reporter",r.Json["items"]![0]!["customer"]!.GetValue<string>());
        await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_report_resolve_fail BEFORE INSERT ON audit_logs FOR EACH ROW BEGIN IF NEW.action='product_report.resolved' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic report rollback'; END IF; END");try{Assert.Equal(500,(await admin.Post($"/api/admin/product-reports/{report}",new{status="resolved",take_down=true,admin_note=" Synthetic action "})).Status);Assert.Equal("approved",await ApiFactory.DbScalarAsync<string>("SELECT status FROM products WHERE id=@pid",new{pid}));Assert.Equal("open",await ApiFactory.DbScalarAsync<string>("SELECT status FROM product_reports WHERE id=@report",new{report}));Assert.Equal(0,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM notifications"));}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_report_resolve_fail");}
        r=await admin.Post($"/api/admin/product-reports/{report}",new{status="resolved",take_down=true,admin_note=" Synthetic action "});Assert.True(r.Status==200,r.ToString());Assert.Equal("rejected",r.Json["product_status"]!.GetValue<string>());Assert.Equal("resolved",await ApiFactory.DbScalarAsync<string>("SELECT status FROM product_reports WHERE id=@other",new{other}));Assert.Equal("Listing taken down",await ApiFactory.DbScalarAsync<string>("SELECT admin_note FROM product_reports WHERE id=@other",new{other}));Assert.Equal(1,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM notifications WHERE user_id=@sid AND channel='inapp'",new{sid=seller.Id}));Assert.Equal(0,(await admin.Get("/api/admin/product-reports")).Json["total"]!.GetValue<long>());Assert.Equal(2,(await admin.Get("/api/admin/product-reports?status=resolved")).Json["total"]!.GetValue<long>());
        Assert.Equal(404,(await admin.Post($"/api/admin/product-reports/{Guid.NewGuid()}",new{status="dismissed"})).Status);Assert.Equal(422,(await admin.Post($"/api/admin/product-reports/{report}",new{status="open"})).Status);Assert.Equal(422,(await admin.Get("/api/admin/reviews?page=0")).Status);

        await ApiFactory.DbExecAsync("UPDATE product_reports SET user_id=NULL WHERE id=@other",new{other});r=await admin.Get("/api/admin/product-reports?status=resolved");Assert.Contains(r.Json["items"]!.AsArray(),x=>x!["customer"]!.GetValue<string>()=="Deleted account");
        Assert.Equal(200,(await admin.Post($"/api/admin/product-reports/{report}",new{status="dismissed",notify_seller=true})).Status);Assert.Equal(1,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM notifications WHERE channel='inapp'"));
        Assert.Equal(200,(await admin.Post($"/api/admin/product-reports/{report}",new{status="resolved",notify_seller=false})).Status);Assert.Equal(1,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM notifications WHERE channel='inapp'"));
        Assert.Equal(200,(await admin.Post($"/api/admin/product-reports/{report}",new{status="resolved",notify_seller=true})).Status);Assert.Equal(2,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM notifications WHERE channel='inapp'"));
        Assert.Equal(0,await ApiFactory.DbScalarAsync<long>("SELECT COUNT(*) FROM notifications WHERE status='sent' AND channel<>'inapp'"));
    }
}
